import { ChangeDetectionStrategy, Component, computed, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  // ngModel on a number input writes null when the field is emptied.
  readonly rowInput = signal<number | null>(3);
  readonly colInput = signal<number | null>(4);

  readonly rows = signal<number[]>([]);
  readonly cols = signal<number[]>([]);
  readonly hasCells = computed(() => this.rows().length > 0 && this.cols().length > 0);

  constructor() {
    this.updateTable();
  }

  private normalizeCount(raw: number | null): number {
    if (raw === null || !Number.isFinite(raw)) {
      return 0;
    }
    const n = Math.floor(raw);
    const clamped = Math.max(0, Math.min(n, 20));
    return clamped;
  }

  updateTable(): void {
    const rows = this.normalizeCount(this.rowInput());
    const cols = this.normalizeCount(this.colInput());

    this.rows.set(Array.from({ length: rows }, (_, i) => i));
    this.cols.set(Array.from({ length: cols }, (_, i) => i));
  }
}
